import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"序章 · 从 50 行代码开始 — 你即将看到的一切 · 参考","description":"","frontmatter":{"title":"序章 · 从 50 行代码开始 — 你即将看到的一切 · 参考","act":0,"kind":"refs","prev":false,"next":{"text":"L01 · 你以为你在思考","link":"/lectures/L01-cognitive-biases/references"}},"headers":[],"relativePath":"lectures/L00-prologue/references.md","filePath":"lectures/L00-prologue/references.md","lastUpdated":null}'),l={name:"lectures/L00-prologue/references.md"};function i(n,s,d,c,f,p){return e(),r("div",null,[...s[0]||(s[0]=[t('<h1 id="l00-参考-·-references-序章-·-从-50-行代码开始-prologue-—-50-lines-of-code" tabindex="-1">L00 参考 · References：序章 · 从 50 行代码开始（Prologue — 50 Lines of Code） <a class="header-anchor" href="#l00-参考-·-references-序章-·-从-50-行代码开始-prologue-—-50-lines-of-code" aria-label="Permalink to &quot;L00 参考 · References：序章 · 从 50 行代码开始（Prologue — 50 Lines of Code）&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: 序章 · 从 50 行代码开始 <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="代码与教程">1. 代码与教程</h2><ol class="ref-list"><li class="ref-item" id="ref-C1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C1</span><a class="ref-title" href="https://github.com/karpathy/nanoGPT" target="_blank" rel="noopener">nanoGPT</a></div><div class="ref-meta">Andrej Karpathy · 2023</div><p class="ref-desc">序章 50 行代码的直接灵感来源。最小可行 Transformer 训练脚本。</p></div></li><li class="ref-item" id="ref-C2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C2</span><a class="ref-title" href="https://github.com/karpathy/makemore" target="_blank" rel="noopener">makemore</a></div><div class="ref-meta">Andrej Karpathy · 2022</div><p class="ref-desc">字符级语言模型从 bigram → MLP → RNN → Transformer 的完整演进。序章代码的教学参考。</p></div></li><li class="ref-item" id="ref-C3"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C3</span><a class="ref-title" href="https://github.com/karpathy/char-rnn" target="_blank" rel="noopener">char-rnn</a></div><div class="ref-meta">Andrej Karpathy · 2015</div><p class="ref-desc">原始字符级 RNN 实验。tinyshakespeare 数据集的来源。</p></div></li><li class="ref-item" id="ref-C4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C4</span><a class="ref-title" href="https://github.com/karpathy/minGPT" target="_blank" rel="noopener">minGPT</a></div><div class="ref-meta">Andrej Karpathy · 2020</div><p class="ref-desc">nanoGPT 的前身，更注重教学可读性。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频">2. 视频</h2><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><a class="ref-title" href="https://www.youtube.com/watch?v=kCc8FmEb1nY" target="_blank" rel="noopener">Let&#39;s build GPT: from scratch, in code, spelled out</a></div><div class="ref-meta">Andrej Karpathy · ~2h</div><p class="ref-desc">必看。从零搭建 GPT 的完整过程。序章 50 行代码是这个 2 小时内容的极致压缩。第 12 讲会回来详细展开。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><a class="ref-title" href="https://www.youtube.com/watch?v=VMj-3S1tku0" target="_blank" rel="noopener">The spelled-out intro to neural networks and backpropagation</a></div><div class="ref-meta">Andrej Karpathy · ~2.5h</div><p class="ref-desc">从零讲梯度与反向传播。序章代码用数值梯度是因为 50 行放不下 autograd——这个视频解释了&quot;真正版本&quot;怎么做。</p></div></li><li class="ref-item" id="ref-V3"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><a class="ref-title" href="https://karpathy.github.io/2015/05/21/rnn-effectiveness/" target="_blank" rel="noopener">The Unreasonable Effectiveness of Recurrent Neural Networks</a></div><div class="ref-meta">Andrej Karpathy · —</div><p class="ref-desc">经典博客。char-rnn 生成莎士比亚、LaTeX、C 代码的著名实验。序章实验的历史原型。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="论文">3. 论文</h2><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noopener">Attention Is All You Need</a></div><div class="ref-meta">Vaswani, A. et al. · 2017 · NeurIPS 2017</div><p class="ref-desc">序章只需知道&quot;这是 50 行代码里注意力层的来源&quot;。第 12 讲逐行拆解。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://cdn.openai.com/better-language-models/language_models_are_unsupervised_multitask_learners.pdf" target="_blank" rel="noopener">Language Models are Unsupervised Multitask Learners</a></div><div class="ref-meta">Radford, A. et al. · 2019 · OpenAI Technical Report</div><p class="ref-desc">GPT-2 论文。&quot;预测下一个词&quot;能做什么？——序章问题的第一个正式回答。第 13 讲详讲。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博客与文章">4. 博客与文章</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://karpathy.github.io/2015/05/21/rnn-effectiveness/" target="_blank" rel="noopener">The Unreasonable Effectiveness of Recurrent Neural Networks</a></div><div class="ref-meta">Andrej Karpathy · 2015</div><p class="ref-desc">经典博文。展示字符级模型生成莎士比亚、维基百科、LaTeX 的惊人效果。</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><a class="ref-title" href="https://colah.github.io/posts/2015-08-Understanding-LSTMs/" target="_blank" rel="noopener">Understanding LSTM Networks</a></div><div class="ref-meta">Chris Olah · 2015</div><p class="ref-desc">背景阅读。序章代码用的是 Attention 而非 LSTM——但了解 RNN 的困难有助于理解为什么 Transformer 赢了。</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><a class="ref-title" href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noopener">The Illustrated Transformer</a></div><div class="ref-meta">Jay Alammar · 2018</div><p class="ref-desc">背景阅读。第 12 讲核心参考，序章只需知道&quot;注意力&quot;的直觉。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="数据集">5. 数据集</h2><ol class="ref-list"><li class="ref-item" id="ref-D1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D1</span><a class="ref-title" href="https://raw.githubusercontent.com/karpathy/char-rnn/master/data/tinyshakespeare/input.txt" target="_blank" rel="noopener">tinyshakespeare</a></div><div class="ref-meta">Andrej Karpathy</div><p class="ref-desc">序章实验使用的数据集。~1MB 莎士比亚全集文本。</p></div></li><li class="ref-item" id="ref-D2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D2</span><a class="ref-title" href="https://huggingface.co/datasets/roneneldan/TinyStories" target="_blank" rel="noopener">TinyStories</a></div><div class="ref-meta">Eldan &amp; Li 2023</div><p class="ref-desc">Microsoft Research 用 GPT-3.5/GPT-4 合成的 ~2GB 三岁儿童词汇故事集。证明 ~10M 参数小模型也能学会&quot;流利英语&quot;。序章可作为&quot;如果你想再小一点&quot;的延伸数据集。</p></div></li><li class="ref-item" id="ref-D3"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D3</span><a class="ref-title" href="https://huggingface.co/datasets/bigcode/the-stack-smol" target="_blank" rel="noopener">The Stack v2 (smol)</a></div><div class="ref-meta">BigCode 2024</div><p class="ref-desc">多语言代码数据集的小样本切片。如果想把序章改成&quot;训练能写 Python 的模型&quot;。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="现代延伸-从-nanogpt-到-nanochat-2024-2026">6. 现代延伸：从 nanoGPT 到 nanochat（2024-2026）</h2><p class="ref-prose">&gt; 这一节追踪 Karpathy 系列教学项目的演进，让学生看到&quot;50 行代码&quot;的思路如何在 2025-2026 年继续生长。</p><ol class="ref-list"><li class="ref-item" id="ref-C5"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C5</span><a class="ref-title" href="https://github.com/karpathy/nanochat" target="_blank" rel="noopener">nanochat</a></div><div class="ref-meta">Andrej Karpathy · 2025</div><p class="ref-desc">Karpathy 2025 年发布的 &quot;$100 ChatGPT clone&quot;。从 tokenizer → pretrain → SFT → RLHF → web UI 全栈 ~8000 行。序章展示&quot;从 50 行到 8000 行&quot;完整光谱。</p></div></li><li class="ref-item" id="ref-C6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C6</span><a class="ref-title" href="https://github.com/KellerJordan/modded-nanoGPT" target="_blank" rel="noopener">modded-nanoGPT</a></div><div class="ref-meta">Keller Jordan et al. · 2024-25</div><p class="ref-desc">&quot;速度榜单&quot;分支：用 Muon 优化器、FlexAttention、Flash Attention 3 把 nanoGPT 训练时间从 45 分钟压到 3 分钟。展示&quot;50 行也能继续优化&quot;。</p></div></li><li class="ref-item" id="ref-C7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C7</span><a class="ref-title" href="https://github.com/karpathy/llm.c" target="_blank" rel="noopener">llm.c</a></div><div class="ref-meta">Andrej Karpathy · 2024</div><p class="ref-desc">用纯 C/CUDA 复现 GPT-2 训练，~1000 行 C 文件训出 GPT-2 124M。&quot;如果你想看没有 PyTorch 的版本&quot;。</p></div></li><li class="ref-item" id="ref-C8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C8</span><a class="ref-title" href="https://github.com/jaymody/picoGPT" target="_blank" rel="noopener">picoGPT</a></div><div class="ref-meta">Jay Mody · 2023</div><p class="ref-desc">~60 行 NumPy 实现 GPT-2 推理（不含训练）。&quot;序章是反过来：60 行训练，picoGPT 是 60 行推理&quot;。</p></div></li><li class="ref-item" id="ref-C9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C9</span><a class="ref-title" href="https://github.com/KellerJordan/modded-nanoGPT/tree/master/records" target="_blank" rel="noopener">NanoGPT speedrun benchmark</a></div><div class="ref-meta">2024-25</div><p class="ref-desc">社群&quot;训练 GPT-2 多快&quot;竞速榜。每月都在被打破。展示工程优化的密度。</p></div></li><li class="ref-item" id="ref-C10"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C10</span><a class="ref-title" href="https://github.com/rasbt/LLMs-from-scratch" target="_blank" rel="noopener">Sebastian Raschka — LLMs from Scratch</a></div><div class="ref-meta">Sebastian Raschka · 2024</div><div class="ref-links"><a class="ref-link" href="https://www.manning.com/books/build-a-large-language-model-from-scratch" target="_blank" rel="noopener">Book</a></div><p class="ref-desc">Manning 出版的&quot;从零构建 LLM&quot;配套代码。每章一个 Jupyter notebook，从 tokenization 一路到 instruction tuning。比 nanoGPT 更教学友好。</p></div></li><li class="ref-item" id="ref-C11"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C11</span><a class="ref-title" href="https://github.com/jzhang38/TinyLlama" target="_blank" rel="noopener">TinyLlama</a></div><div class="ref-meta">TinyLlama team · 2024</div><p class="ref-desc">1.1B 参数、3T tokens 的开源小模型，完整训练 recipe 公开。&quot;如果你想训一个真能用的&quot;。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="行业讲座与思想领袖-2023-2026">7. 行业讲座与思想领袖（2023-2026）</h2><p class="ref-prose">&gt; 序章需要建立&quot;为什么这门课重要&quot;的语境。这些讲座从产业一线视角回答了同一个问题。</p><ol class="ref-list"><li class="ref-item" id="ref-T1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T1</span><a class="ref-title" href="https://www.youtube.com/watch?v=zjkBMFhNj_g" target="_blank" rel="noopener">Intro to Large Language Models</a></div><div class="ref-meta">Andrej Karpathy · 2023</div><p class="ref-desc">1 小时 LLM 全景图。&quot;当我们说 LLM 是什么&quot;——序章可借用其中&quot;两个文件 = 一个模型&quot;的隐喻：parameters.bin + run.py。</p></div></li><li class="ref-item" id="ref-T2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T2</span><a class="ref-title" href="https://search.bilibili.com/all?keyword=Karpathy+Intro+to+LLM" target="_blank" rel="noopener"><strong>[1hr Talk] Intro to Large Language Models</strong>（中文字幕版）</a></div><div class="ref-meta">Andrej Karpathy · 2023</div><p class="ref-desc">中文区学生友好版本。</p></div></li><li class="ref-item" id="ref-T3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T3</span><a class="ref-title" href="https://www.youtube.com/watch?v=bZQun8Y4L2A" target="_blank" rel="noopener">State of GPT</a></div><div class="ref-meta">Andrej Karpathy · 2023</div><div class="ref-links"><a class="ref-link" href="https://build.microsoft.com/en-US/sessions/db3f4859-cd30-4445-a0cd-553c3304f8e2" target="_blank" rel="noopener">Microsoft Build</a></div><p class="ref-desc">Build 大会主题演讲。&quot;GPT 助理训练流水线&quot; 4 阶段图（pretrain → SFT → reward → RLHF）已成行业标准插图。</p></div></li><li class="ref-item" id="ref-T4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T4</span><a class="ref-title" href="https://www.youtube.com/watch?v=7xTGNNLPyMI" target="_blank" rel="noopener">Deep Dive into LLMs like ChatGPT</a></div><div class="ref-meta">Andrej Karpathy · 2025</div><p class="ref-desc">2025 年 3.5 小时新版深讲，覆盖 pretraining → post-training → RLHF → reasoning models 全栈。序章可挑选 5-10 分钟&quot;什么是预训练&quot;片段。</p></div></li><li class="ref-item" id="ref-T5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T5</span><a class="ref-title" href="https://www.youtube.com/watch?v=EWvNQjAaOHw" target="_blank" rel="noopener">How I use LLMs</a></div><div class="ref-meta">Andrej Karpathy · 2025</div><p class="ref-desc">第一人称工作流分享：他每天用 LLM 做什么。可作为&quot;贯穿项目（个人 AI 助手）&quot;的产品视野参考。</p></div></li><li class="ref-item" id="ref-T6"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T6</span><span class="ref-title">The Bitter Lesson, Reconsidered</span></div><div class="ref-meta">Sutton / various · 2024-25</div><p class="ref-desc">Sutton 2019 经典短文 <a href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noopener">&quot;The Bitter Lesson&quot;</a> 在 2024-25 年被反复重读。序章&quot;50 行 vs 大模型&quot;的张力直接呼应。</p></div></li><li class="ref-item" id="ref-T7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T7</span><a class="ref-title" href="https://www.youtube.com/watch?v=LCEmiRjPEtQ" target="_blank" rel="noopener">Software Is Changing (Again)</a></div><div class="ref-meta">Andrej Karpathy · 2025</div><p class="ref-desc">Karpathy 在 YC AI Startup School 的演讲：&quot;Software 1.0 = 代码、2.0 = 神经网络权重、3.0 = prompt&quot;。序章可借用 1.0/2.0/3.0 框架。</p></div></li><li class="ref-item" id="ref-T8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T8</span><a class="ref-title" href="https://the-coming-wave.com/" target="_blank" rel="noopener"><strong>The Coming Wave</strong>（书 + 巡讲）</a></div><div class="ref-meta">Mustafa Suleyman · 2023</div><p class="ref-desc">DeepMind 联合创始人对 AI + 合成生物 &quot;containment problem&quot; 的产业视角。给&quot;为什么这门课的伦理章节存在&quot;做铺垫。</p></div></li><li class="ref-item" id="ref-T9"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T9</span><a class="ref-title" href="https://www.anthropic.com/news/machines-of-loving-grace" target="_blank" rel="noopener">Compute Is the Strategy: A View From the Trenches</a></div><div class="ref-meta">Dario Amodei (Anthropic) · 2024</div><p class="ref-desc">Anthropic CEO 的长文，对 AGI 时间表与社会影响的产业最权威表态之一。</p></div></li><li class="ref-item" id="ref-T10"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T10</span><span class="ref-title">Sam Altman: How AI is Reshaping the Future of Work</span></div><div class="ref-meta">Sam Altman · 2024-25</div><p class="ref-desc">OpenAI CEO 的产业视角。注意：常被批评&quot;过度乐观&quot;——可作为&quot;不要只听一家&quot;的反例。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="播客与长访谈-2024-2026">8. 播客与长访谈（2024-2026）</h2><p class="ref-prose">&gt; 序章前的&quot;暖身&quot;或课程主页推荐听单。每一集都对应课程后续某讲。</p><ol class="ref-list"><li class="ref-item" id="ref-PC1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC1</span><a class="ref-title" href="https://lexfridman.com/sam-altman-2/" target="_blank" rel="noopener">#367 — Sam Altman: OpenAI, GPT-5, Sora, Body, AGI</a></div><div class="ref-meta">Lex Fridman Podcast · 2024 · ~1.5h</div><p class="ref-desc">L14 (Scaling), L34 (Safety), L35 (Predictions)</p></div></li><li class="ref-item" id="ref-PC2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC2</span><a class="ref-title" href="https://lexfridman.com/andrej-karpathy/" target="_blank" rel="noopener">#386 — Andrej Karpathy: Tesla AI, Self-Driving, Optimus, Aliens</a></div><div class="ref-meta">Lex Fridman Podcast · 2024 · ~3.5h</div><p class="ref-desc">L00 (序章工程审美), L33 (Embodied AI)</p></div></li><li class="ref-item" id="ref-PC3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC3</span><a class="ref-title" href="https://lexfridman.com/dario-amodei/" target="_blank" rel="noopener">#452 — Dario Amodei: Anthropic CEO on Claude, AGI, and the Future of Humanity</a></div><div class="ref-meta">Lex Fridman Podcast · 2024 · ~5h</div><p class="ref-desc">L18 (Alignment), L34 (Safety), L35 (Predictions)</p></div></li><li class="ref-item" id="ref-PC4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC4</span><a class="ref-title" href="https://lexfridman.com/demis-hassabis-2/" target="_blank" rel="noopener">Demis Hassabis on AlphaFold, AGI, and the Future of AI</a></div><div class="ref-meta">Lex Fridman Podcast · 2024-25 · ~2h</div><p class="ref-desc">L17 (RL), L29 (Multimodal), L33 (Embodied)</p></div></li><li class="ref-item" id="ref-PC5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC5</span><a class="ref-title" href="https://lexfridman.com/yann-lecun-3/" target="_blank" rel="noopener">Yann LeCun: Limits of LLMs, AGI &amp; the Future of AI</a></div><div class="ref-meta">Lex Fridman Podcast · 2024 · ~3h</div><p class="ref-desc">L20 (Reasoning, &quot;LLMs cannot reason&quot;), L33 (World Models)</p></div></li><li class="ref-item" id="ref-PC6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC6</span><a class="ref-title" href="https://www.cognitiverevolution.ai/" target="_blank" rel="noopener">The Cognitive Revolution Podcast</a></div><div class="ref-meta">Erik Torenberg, Nathan Labenz · 2023-26 · weekly</div><p class="ref-desc">高密度 LLM 实践访谈。每周新研究/新产品深度解读。</p></div></li><li class="ref-item" id="ref-PC7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC7</span><a class="ref-title" href="https://www.latent.space/" target="_blank" rel="noopener">Latent Space Podcast</a></div><div class="ref-meta">swyx, Alessio · 2023-26 · weekly</div><p class="ref-desc">工程视角的&quot;AI engineer&quot;播客。L26-L31 多次被引用。</p></div></li><li class="ref-item" id="ref-PC8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC8</span><a class="ref-title" href="https://www.dwarkesh.com/" target="_blank" rel="noopener">Dwarkesh Podcast (formerly The Lunar Society)</a></div><div class="ref-meta">Dwarkesh Patel · 2023-26 · weekly</div><p class="ref-desc">长达 3-4 小时深度访谈。包括 Sholto Douglas/Trenton Bricken (Anthropic), Sutton, Hassabis 等。</p></div></li><li class="ref-item" id="ref-PC9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC9</span><a class="ref-title" href="https://www.aiengineer.foundation/" target="_blank" rel="noopener">AI Engineer Summit / World&#39;s Fair Talks</a></div><div class="ref-meta">swyx + community · 2024-26 · varied</div><p class="ref-desc">工程师视角的&quot;现在的 AI 长什么样&quot;。L26 之后多讲会引用。</p></div></li><li class="ref-item" id="ref-PC10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC10</span><a class="ref-title" href="https://www.no-priors.com/" target="_blank" rel="noopener">No Priors Podcast</a></div><div class="ref-meta">Sarah Guo, Elad Gil · 2023-26 · weekly</div><p class="ref-desc">创投视角的 AI 产业访谈。CEO/CTO 嘉宾密度高。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="经典与现代博文-课前推荐预读">9. 经典与现代博文：课前推荐预读</h2><ol class="ref-list"><li class="ref-item" id="ref-A4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><a class="ref-title" href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noopener">The Bitter Lesson</a></div><div class="ref-meta">Richard Sutton · 2019</div><p class="ref-desc">5 段话短文。所有 &quot;70 年 AI 史&quot;叙事的最佳压缩。&quot;通用方法 + 算力 &gt; 人类先验&quot;。</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><a class="ref-title" href="https://karpathy.medium.com/software-2-0-a64152b37c35" target="_blank" rel="noopener">Software 2.0</a></div><div class="ref-meta">Andrej Karpathy · 2017</div><p class="ref-desc">&quot;代码不再写，而是被训出来的&quot;。 序章 50 行代码就是 Software 2.0 的最小完整实现。</p></div></li><li class="ref-item" id="ref-A6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A6</span><a class="ref-title" href="http://karpathy.github.io/2019/04/25/recipe/" target="_blank" rel="noopener">A Recipe for Training Neural Networks</a></div><div class="ref-meta">Andrej Karpathy · 2019</div><p class="ref-desc">&quot;Yes you should understand backprop&quot; 的姊妹篇。给&quot;代码能跑 ≠ 模型对了&quot;做警示。</p></div></li><li class="ref-item" id="ref-A7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A7</span><a class="ref-title" href="https://karpathy.medium.com/yes-you-should-understand-backprop-e2f06eab496b" target="_blank" rel="noopener">Yes, you should understand backprop</a></div><div class="ref-meta">Andrej Karpathy · 2016</div><p class="ref-desc">序章用数值梯度——这篇解释为什么真实工程中你必须理解 autograd。</p></div></li><li class="ref-item" id="ref-A8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A8</span><a class="ref-title" href="https://openai.com/research/generative-models" target="_blank" rel="noopener">Generative Models</a></div><div class="ref-meta">OpenAI (Goodfellow) · 2016</div><p class="ref-desc">&quot;What I cannot create, I do not understand.&quot; (Feynman 引用)——这是序章演示的精神内核。</p></div></li><li class="ref-item" id="ref-A9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A9</span><a class="ref-title" href="https://www.dartmouth.edu/~matc/MathDrama/reading/Wigner.pdf" target="_blank" rel="noopener">The Unreasonable Effectiveness of Mathematics in the Natural Sciences</a></div><div class="ref-meta">Eugene Wigner · 1960</div><p class="ref-desc">Karpathy 的 &quot;Unreasonable Effectiveness of RNN&quot; 标题来源。哲学色彩，给课程做形而上铺垫。</p></div></li><li class="ref-item" id="ref-A10"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A10</span><a class="ref-title" href="https://jaykmody.com/blog/gpt-from-scratch/" target="_blank" rel="noopener">GPT in 60 Lines of NumPy</a></div><div class="ref-meta">Jay Mody · 2023</div><p class="ref-desc">picoGPT 配套博文。&quot;如何在 60 行 NumPy 里实现 GPT-2 推理&quot;。和序章训练版互补。</p></div></li><li class="ref-item" id="ref-A11"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A11</span><a class="ref-title" href="https://nlp.seas.harvard.edu/annotated-transformer/" target="_blank" rel="noopener">The Annotated Transformer</a></div><div class="ref-meta">Sasha Rush et al. · 2018 / 2022 重写</div><p class="ref-desc">Harvard NLP 经典：每行 Transformer 论文配代码。如果学生想&quot;从论文走到代码&quot;。</p></div></li><li class="ref-item" id="ref-A12"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A12</span><a class="ref-title" href="https://transformer-circuits.pub/2021/framework/index.html" target="_blank" rel="noopener">A Mathematical Framework for Transformer Circuits</a></div><div class="ref-meta">Anthropic / Elhage et al. · 2021</div><p class="ref-desc">进阶。如果学生想问&quot;模型内部到底在算什么&quot;——这是机制可解释性社区的奠基工作。</p></div></li><li class="ref-item" id="ref-A13"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A13</span><a class="ref-title" href="https://simonwillison.net/2024/Dec/31/llms-in-2024/" target="_blank" rel="noopener">Things We Learned About LLMs in 2024</a></div><div class="ref-meta">Simon Willison · 2024</div><p class="ref-desc">必读。把&quot;过去一年 LLM 进展&quot;压缩成 30 个要点。课程开学前的最佳定向材料。</p></div></li><li class="ref-item" id="ref-A14"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A14</span><a class="ref-title" href="https://simonwillison.net/series/llms-in-2024/" target="_blank" rel="noopener"><strong>Things I Learned About LLMs in 2025</strong> (annual sequel)</a></div><div class="ref-meta">Simon Willison · 2025</div><p class="ref-desc">同上，2025 年版。</p></div></li><li class="ref-item" id="ref-A15"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A15</span><a class="ref-title" href="https://nonint.com/2023/06/10/the-it-in-ai-models-is-the-dataset/" target="_blank" rel="noopener">The &quot;It&quot; in AI models is the dataset</a></div><div class="ref-meta">James Betker (OpenAI) · 2023</div><p class="ref-desc">&quot;你训练的不是模型，是数据集的拟合体。&quot;序章数据集只有 1MB，效果上限就在那里——一句话点明。</p></div></li><li class="ref-item" id="ref-A16"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A16</span><a class="ref-title" href="https://newsletter.maartengrootendorst.com/p/a-visual-guide-to-mamba-and-state" target="_blank" rel="noopener">A Visual Guide to Mamba and State Space Models</a></div><div class="ref-meta">Maarten Grootendorst · 2024</div><p class="ref-desc">选读。如果有学生问&quot;还有别的架构吗&quot;——SSM 是 2024-25 年最重要的 Transformer 替代候选之一。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="序章选讲-纪录片与历史短片-选听氛围">10. 序章选讲：纪录片与历史短片（选听氛围）</h2><ol class="ref-list"><li class="ref-item" id="ref-F1"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">F1</span><a class="ref-title" href="https://www.youtube.com/watch?v=WXuK6gekU1Y" target="_blank" rel="noopener">AlphaGo — The Movie</a></div><div class="ref-meta">2017</div><p class="ref-desc">90 分钟纪录片。如果开课前想给学生 &quot;AI 时刻&quot; 的情感锚点。</p></div></li><li class="ref-item" id="ref-F2"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">F2</span><span class="ref-title"><strong>The Thinking Game</strong> (DeepMind/Hassabis)</span></div><div class="ref-meta">2024</div><p class="ref-desc">Hassabis 与 DeepMind 故事的官方纪录片。覆盖 AlphaGo→AlphaFold→Gemini。</p></div></li><li class="ref-item" id="ref-F3"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">F3</span><a class="ref-title" href="https://www.pbs.org/wgbh/frontline/documentary/in-the-age-of-ai/" target="_blank" rel="noopener"><strong>In the Age of AI</strong>（PBS Frontline）</a></div><div class="ref-meta">2019</div><p class="ref-desc">2 小时电视纪录片。中美 AI 竞争视角，给&quot;非技术听众&quot;做背景。</p></div></li><li class="ref-item" id="ref-F4"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">F4</span><span class="ref-title"><strong>Coded Bias</strong>（Joy Buolamwini）</span></div><div class="ref-meta">2020</div><p class="ref-desc">算法偏见纪录片。L34 Safety 讲的预读。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="中文社区与学者视角">11. 中文社区与学者视角</h2><p class="ref-prose">&gt; 中文学生友好的高质量入门材料，可作为序章后的延伸阅读。</p><ol class="ref-list"><li class="ref-item" id="ref-Z1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z1</span><a class="ref-title" href="https://udlbook.github.io/udlbook/" target="_blank" rel="noopener">Understanding Deep Learning（中译）</a></div><div class="ref-meta">Simon J.D. Prince（中文翻译版） · 2024</div><p class="ref-desc">免费 PDF。当代最好的深度学习教科书之一。中文社区有翻译。</p></div></li><li class="ref-item" id="ref-Z2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z2</span><a class="ref-title" href="https://github.com/datawhalechina/llm-cookbook" target="_blank" rel="noopener">大模型炼丹指南</a></div><div class="ref-meta">邱锡鹏 / 复旦 NLP · 2023-25</div><p class="ref-desc">Datawhale 社区维护的中文 LLM 实践手册。</p></div></li><li class="ref-item" id="ref-Z3"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z3</span><span class="ref-title">机器之心 / 量子位 / AI 科技评论</span></div><div class="ref-meta">Synced / QbitAI / AITech Review · ongoing</div><p class="ref-desc">中文 AI 行业新闻三大头部。每周关注可以追上学术 + 产业进展。</p></div></li><li class="ref-item" id="ref-Z4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z4</span><a class="ref-title" href="https://bbycroft.net/llm" target="_blank" rel="noopener">LLM Visualization（中文版）</a></div><div class="ref-meta">bbycroft / 第三方翻译 · 2023</div><p class="ref-desc">浏览器内 3D 可视化 GPT 推理过程。序章演示的最佳&quot;它在算什么&quot;动画。</p></div></li><li class="ref-item" id="ref-Z5"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z5</span><span class="ref-title">复旦 MOSS / 智源 / 上海 AI Lab 公开课</span></div><div class="ref-meta">各机构 · 2024-26</div><p class="ref-desc">国内顶级实验室的公开课资源，质量参差但覆盖面广。</p></div></li><li class="ref-item" id="ref-Z6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z6</span><a class="ref-title" href="https://search.bilibili.com/all?keyword=Karpathy" target="_blank" rel="noopener">Karpathy 系列视频中文字幕</a></div><div class="ref-meta">B 站 UP 主翻译 · 2023-25</div><p class="ref-desc">几乎所有 Karpathy 视频都有中文字幕版。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="关于本课程的-参考资料的参考资料">12. 关于本课程的&quot;参考资料的参考资料&quot;</h2><ol class="ref-list"><li class="ref-item" id="ref-M1"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M1</span><a class="ref-title" href="https://github.com/Hannibal046/Awesome-LLM" target="_blank" rel="noopener">Awesome LLM</a></div><div class="ref-meta">Hannibal046 et al.</div><p class="ref-desc">GitHub 上最大的 LLM 资源汇总。论文、代码、模型、教程一网打尽。</p></div></li><li class="ref-item" id="ref-M2"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M2</span><a class="ref-title" href="https://github.com/f/awesome-chatgpt-prompts" target="_blank" rel="noopener">Awesome ChatGPT Prompts</a></div><div class="ref-meta">f / community</div><p class="ref-desc">Prompt 模板库，L21-L22 会用到。</p></div></li><li class="ref-item" id="ref-M3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M3</span><a class="ref-title" href="https://huggingface.co/papers" target="_blank" rel="noopener">Hugging Face Daily Papers</a></div><div class="ref-meta">Hugging Face</div><p class="ref-desc">每日精选 arXiv 新论文 + 社区投票。课程&quot;持续更新&quot;的最佳订阅源。</p></div></li><li class="ref-item" id="ref-M4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M4</span><a class="ref-title" href="https://x.com/_akhaliq" target="_blank" rel="noopener">AK&#39;s Twitter / X feed (@_akhaliq)</a></div><div class="ref-meta">@_akhaliq</div><p class="ref-desc">最及时的&quot;今天有什么新论文&quot;播报。</p></div></li><li class="ref-item" id="ref-M5"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M5</span><a class="ref-title" href="https://www.deeplearning.ai/the-batch/" target="_blank" rel="noopener">The Batch / DeepLearning.AI Newsletter</a></div><div class="ref-meta">Andrew Ng</div><p class="ref-desc">周报，行业新闻 + Andrew Ng 短评。新闻向。</p></div></li><li class="ref-item" id="ref-M6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M6</span><a class="ref-title" href="https://importai.substack.com/" target="_blank" rel="noopener">Import AI Newsletter</a></div><div class="ref-meta">Jack Clark (Anthropic)</div><p class="ref-desc">周报，policy + 产业 + 论文混合。Anthropic policy 主管亲笔。</p></div></li><li class="ref-item" id="ref-M7"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M7</span><a class="ref-title" href="https://alphasignal.ai/" target="_blank" rel="noopener">AlphaSignal</a></div><div class="ref-meta">Lior Sinclair</div><p class="ref-desc">工程师向日报。模型发布、benchmark 更新、工具榜单。</p></div></li><li class="ref-item" id="ref-M8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M8</span><a class="ref-title" href="https://every.to/chain-of-thought" target="_blank" rel="noopener">Every: Chain of Thought</a></div><div class="ref-meta">Dan Shipper</div><p class="ref-desc">散文向产品评测。给&quot;非工程师如何看 AI&quot;角度。</p></div></li><li class="ref-item" id="ref-M9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M9</span><a class="ref-title" href="https://tldr.tech/ai" target="_blank" rel="noopener">TLDR AI</a></div><div class="ref-meta">TLDR Newsletter</div><p class="ref-desc">5 分钟读完的日报。</p></div></li><li class="ref-item" id="ref-M10"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">M10</span><a class="ref-title" href="https://magazine.sebastianraschka.com/" target="_blank" rel="noopener">Ahead of AI / Sebastian Raschka</a></div><div class="ref-meta">Sebastian Raschka</div><p class="ref-desc">月度技术深度长文。Sebastian 是 PyTorch Lightning / LLMs from Scratch 作者。</p></div></li></ol></section>',16)])])}const h=a(l,[["render",i]]);export{v as __pageData,h as default};
